mapper.select:
SELECT tenant_id,idempotency_key,command_kind,command_data,result_fact_id,result_revision
  FROM public.agent_runtime_memory_operations
 WHERE tenant_id=#{tenant} AND idempotency_key=#{key}

SELECT occurred_at_epoch_second AS epoch_second,occurred_at_nano AS nano
  FROM public.agent_runtime_session_events
 WHERE tenant_id=#{tenant} AND target_kind=#{targetKind} AND target_id=#{targetId}
   AND (agent_id=#{agentId} OR target_kind='GROUP') AND session_id=#{sessionId}
   AND event_id IN
   #{event}

SELECT fact_id,revision FROM public.agent_runtime_memory_extraction_evidence
 WHERE tenant_id=#{tenant} AND extraction_digest=#{digest} AND source_target_kind=#{targetKind}
   AND source_target_id=#{targetId} AND source_session_id=#{sessionId}
   AND source_event_id=#{eventId} AND extractor_version=#{extractor}

mapper.sql:
, documents AS MATERIALIZED (
SELECT a.fact_id,a.revision,a.content_revision,d.search_text,d.text_digest,d.lexical_terms FROM authorized a
LEFT JOIN public.agent_runtime_memory_search_documents d ON d.tenant_id=#{filter.tenant} AND d.fact_id=a.fact_id
  AND d.content_revision=a.content_revision AND d.projection_version=#{filter.projectionVersion} AND d.analyzer_version=#{filter.analyzerVersion}
), vectors AS MATERIALIZED (
SELECT d.fact_id,d.revision,d.content_revision,d.search_text,d.text_digest,d.lexical_terms,e.embedding
  FROM documents d JOIN public.agent_runtime_memory_embeddings e
  ON e.tenant_id=#{filter.tenant} AND e.fact_id=d.fact_id AND e.content_revision=d.content_revision
  AND e.projection_version=#{filter.projectionVersion} AND e.analyzer_version=#{filter.analyzerVersion}
  AND e.model_id=#{filter.modelId,jdbcType=VARCHAR} AND e.model_revision=#{filter.modelRevision,jdbcType=BIGINT}
  AND e.dimensions=#{filter.dimensions,jdbcType=INTEGER} AND vector_dims(e.embedding)=#{filter.dimensions,jdbcType=INTEGER}
  AND e.text_digest=d.text_digest AND e.state='READY')

mapper.select:

SELECT d.fact_id,a.revision,ts_rank(d.lexical_terms,CAST(#{filter.queryLexemes} AS tsquery))::double precision score
  FROM public.agent_runtime_memory_search_documents d
  JOIN authorized a ON a.fact_id=d.fact_id AND a.content_revision=d.content_revision
 WHERE d.tenant_id=#{filter.tenant} AND d.projection_version=#{filter.projectionVersion}
   AND d.analyzer_version=#{filter.analyzerVersion}
   AND d.lexical_terms @@ CAST(#{filter.queryLexemes} AS tsquery)
  ORDER BY score DESC,d.fact_id,a.revision LIMIT #{filter.candidateLimit}


SELECT fact_id,revision,1-(embedding <=> CAST(#{filter.vectorText} AS vector)) score
  FROM vectors WHERE 1-(embedding <=> CAST(#{filter.vectorText} AS vector))>=#{filter.cosineMinimum}
  ORDER BY score DESC,fact_id,revision LIMIT #{filter.candidateLimit}

SELECT tenant_id,fact_id,content_revision,projection_version,analyzer_version,search_text,text_digest,run_data,identity_data
  FROM public.agent_runtime_memory_search_documents WHERE tenant_id=#{tenantId} AND fact_id=#{factId} AND content_revision=#{contentRevision}
  AND projection_version=#{projectionVersion} AND analyzer_version=#{analyzerVersion}

mapper.update:
UPDATE public.agent_runtime_memory_embeddings e SET state=#{state},embedding=CAST(#{vector,jdbcType=VARCHAR} AS vector),reason_code=#{reason,jdbcType=VARCHAR},lease_token=NULL,lease_until=NULL,updated_at=clock_timestamp()
 WHERE e.tenant_id=#{work.tenantId.value} AND e.invocation_id=#{work.invocationId}
  AND e.fact_id=#{work.factId} AND e.content_revision=#{work.contentRevision}
  AND e.projection_version=#{work.projectionVersion} AND e.analyzer_version=#{work.analyzerVersion} AND e.state='RUNNING' AND e.lease_token=#{work.leaseToken}
  AND e.lease_until>clock_timestamp() AND e.text_digest=#{work.textDigest}
  AND e.model_id=#{work.model.modelConfigId} AND e.model_revision=#{work.model.revision} AND e.dimensions=#{work.model.dimensions}
  AND EXISTS(SELECT 1 FROM public.agent_runtime_memory_search_documents d WHERE d.tenant_id=e.tenant_id AND d.fact_id=e.fact_id
   AND d.content_revision=e.content_revision AND d.projection_version=e.projection_version AND d.analyzer_version=e.analyzer_version AND d.text_digest=e.text_digest)
